UPDATE operation_base.t_operation_base_group_map_enterprise
SET group_code = #{operationGroupMapEnterpriseRpcDTO.groupCode},
    remark     = #{operationGroupMapEnterpriseRpcDTO.remark}
WHERE delete_flag = false
  AND enterprise_code = #{operationGroupMapEnterpriseRpcDTO.enterpriseCode}

UPDATE operation_base.t_operation_base_group_map_enterprise
SET principal_user_code = #{operationGroupMapEnterpriseRpcDTO.principalUserCode}
WHERE delete_flag = false
  AND group_code = #{operationGroupMapEnterpriseRpcDTO.groupCode}
  AND enterprise_code = #{operationGroupMapEnterpriseRpcDTO.enterpriseCode}

UPDATE operation_base.t_operation_base_group
SET delete_flag = false

    , group_name = #{operationGroupRpcDTO.groupName}


    , group_principal_user_code = #{operationGroupRpcDTO.groupPrincipalUserCode}

, remark = #{operationGroupRpcDTO.remark}
WHERE delete_flag = false
AND group_code = #{operationGroupRpcDTO.groupCode}

