SELECT COUNT(id)
FROM operation_base.t_operation_base_group_map_user
WHERE delete_flag = false
  AND group_code = #{groupCode}
  AND user_code = #{userCode}

SELECT COUNT(id)
FROM operation_base.t_operation_base_group_map_enterprise
WHERE delete_flag = false
  AND group_code = #{groupCode}
  AND enterprise_code = #{enterpriseCode}

SELECT t1.enterprise_code, t1.principal_user_code, t2.operation_user_name AS principal_user_name FROM operation_base.t_operation_base_group_map_enterprise t1 LEFT JOIN operation_base.t_operation_base_user t2 ON t1.principal_user_code = t2.operation_user_code WHERE t1.enterprise_code IN
#{enterpriseCode}
AND t1.delete_flag = false AND t2.delete_flag = false
